func (d *Droid) IsTransientError(out Output, err error) bool {
	if err == nil {
		return false
	}
	combined := out.Stdout + out.Stderr
	transientPatterns := []string{
		"overloaded",
		"rate limit",
		"529",
		"503",
		"ECONNRESET",
		"ETIMEDOUT",
	}
	for _, p := range transientPatterns {
		if strings.Contains(combined, p) {
			return true
		}
	}
	return false
}

// droidSettings represents the ~/.factory/settings.json structure used for
// BYOK (Bring Your Own Key) configuration.
type droidSettings struct {
	CustomModels []droidCustomModel `json:"customModels,omitempty"`
}

type droidCustomModel struct {
	DisplayName    string `json:"displayName"`
	Model          string `json:"model"`
	BaseURL        string `json:"baseUrl"`
	APIKey         string `json:"apiKey"`
	Provider       string `json:"provider"`
	MaxOutputToken int    `json:"maxOutputTokens"`
}

const (
	// Droid v0.63+ expects custom model selection using custom:<model-id>.
	// The displayName in settings is not accepted by --model.
	droidCustomModelDisplayName = "claude-haiku-custom"
	droidCustomModelBaseID      = "claude-haiku-4-5-20251001"
	defaultDroidModel           = "custom:" + droidCustomModelBaseID
)

// DefaultDroidModel returns the default model string for Droid BYOK configuration.
// Format is "custom:<baseModelID>" which the Droid API expects for custom model selection.
func DefaultDroidModel() string { return defaultDroidModel }

func (d *Droid) Bootstrap() error {
	apiKey := os.Getenv("ANTHROPIC_API_KEY")
	if apiKey == "" {
		return nil
	}

	home, err := os.UserHomeDir()
	if err != nil {
		return fmt.Errorf("get home dir: %w", err)
	}
	dir := filepath.Join(home, ".factory")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return fmt.Errorf("mkdir %s: %w", dir, err)
	}

	settingsPath := filepath.Join(dir, "settings.json")

	// Read existing settings to merge (hooks may already be configured
	// in the repo-local .factory/settings.json, but the global config
	// at ~/.factory/settings.json might have other pre-existing entries).
	var settings droidSettings
	if data, readErr := os.ReadFile(settingsPath); readErr == nil {
		// Best-effort merge: ignore parse errors and start fresh
		_ = json.Unmarshal(data, &settings)
	}

	// Replace or add the BYOK model entry.
	byokModel := droidCustomModel{
		DisplayName:    droidCustomModelDisplayName,
		Model:          droidCustomModelBaseID,
		BaseURL:        "https://api.anthropic.com",
		APIKey:         apiKey,
		Provider:       "anthropic",
		MaxOutputToken: 8192,
	}

	found := false
	for i, m := range settings.CustomModels {
		if m.Model == byokModel.Model {
			settings.CustomModels[i] = byokModel
			found = true
			break
		}
	}
	if !found {
		settings.CustomModels = append(settings.CustomModels, byokModel)
	}

	data, err := json.MarshalIndent(settings, "", "  ")
	if err != nil {
		return fmt.Errorf("marshal settings: %w", err)
	}
	return os.WriteFile(settingsPath, data, 0o644)
}

func (d *Droid) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
	cfg := &runConfig{Model: defaultDroidModel}
	for _, o := range opts {
		o(cfg)
	}

	model := cfg.Model
	if model == "" {
		model = defaultDroidModel
	}

	args := []string{"exec", "--skip-permissions-unsafe", "--model", model, prompt}
	displayArgs := []string{"exec", "--skip-permissions-unsafe", "--model", model, fmt.Sprintf("%q", prompt)}

	cmd := exec.CommandContext(ctx, d.Binary(), args...)
	cmd.Dir = dir
	cmd.Stdin = nil
	cmd.Env = filterEnv(os.Environ(), "ENTIRE_TEST_TTY", "CI", "GITHUB_ACTIONS")
	setupProcessGroup(cmd)
	cmd.WaitDelay = 5 * time.Second

	var stdout, stderr strings.Builder
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	err := cmd.Run()
	exitCode := 0
	if err != nil {
		exitErr := &exec.ExitError{}
		if errors.As(err, &exitErr) {
			exitCode = exitErr.ExitCode()
		} else {
			exitCode = -1
		}
	}

	return Output{
		Command:  d.Binary() + " " + strings.Join(displayArgs, " "),
		Stdout:   stdout.String(),
		Stderr:   stderr.String(),
		ExitCode: exitCode,
	}, err
}

func (d *Droid) StartSession(ctx context.Context, dir string) (Session, error) {
	name := fmt.Sprintf("droid-test-%d", time.Now().UnixNano())
	// Unset CI and GITHUB_ACTIONS so Droid doesn't enter single-turn/headless
	// mode — it checks these vars and skips interactive input after the first turn.
	s, err := NewTmuxSession(name, dir, []string{"CI", "GITHUB_ACTIONS", "ENTIRE_TEST_TTY"}, d.Binary())
	if err != nil {
		return nil, err
	}

	// Dismiss startup dialogs (folder trust, etc.) then wait for the input
	// prompt. Droid v0.178.0 added a "Trust this folder?" dialog in interactive
	// mode for untrusted directories. Its "1. Trust this folder" option is
	// pre-selected, so Enter confirms it. The dialog renders its selected option
	// as "> 1. Trust this folder", so a bare ">" match cannot distinguish the
	// dialog from the real input box — we must key off the dialog chrome (see
	// isDroidStartupDialog) before treating ">" as ready.

// AssertNewCommits polls until at least `atLeast` new commits exist since setup,
// or fails after 20 seconds. Polling handles the race where an interactive
// agent's prompt pattern appears before its git commit lands on disk.
func AssertNewCommits(t *testing.T, s *RepoState, atLeast int) {
	t.Helper()
	AssertNewCommitsWithTimeout(t, s, atLeast, 20*time.Second)
}

// AssertNewCommitsWithTimeout is like AssertNewCommits but with a configurable
// timeout. Use this when WaitFor may settle on stale pane content (e.g.
// multi-turn interactive tests where the previous turn's prompt is still
// visible), giving the agent more time to complete its commit.
func AssertNewCommitsWithTimeout(t *testing.T, s *RepoState, atLeast int, timeout time.Duration) {
	t.Helper()
	deadline := time.Now().Add(timeout)
	for {
		out := GitOutput(t, s.Dir, "log", "--oneline", s.HeadBefore+"..HEAD")
		var lines []string
		if out != "" {
			lines = strings.Split(strings.TrimSpace(out), "\n")
		}
		if len(lines) >= atLeast {
			return
		}
		if time.Now().After(deadline) {
			t.Fatalf("expected at least %d new commit(s), got %d after %s", atLeast, len(lines), timeout)
		}
		time.Sleep(500 * time.Millisecond)
	}
}

// WaitForCheckpoint polls until the checkpoint branch advances from its
// initial state, or fails the test after timeout. Use this before any
// assertions that depend on the checkpoint branch (post-commit hook is async).
func WaitForCheckpoint(t *testing.T, s *RepoState, timeout time.Duration) {
	t.Helper()
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		if CheckpointState(s.Dir) != s.CheckpointBefore {
			return
		}
		time.Sleep(200 * time.Millisecond)
	}
	t.Fatalf("checkpoint state did not advance within %s", timeout)
}

// ShadowBranches returns all shadow branches (entire/*) excluding entire/checkpoints/*.
func ShadowBranches(t *testing.T, dir string) []string {
	t.Helper()
	branches := GitOutput(t, dir, "for-each-ref", "--format=%(refname:short)", "refs/heads/entire/")
	var shadow []string
	for _, b := range strings.Split(branches, "\n") {
		b = strings.TrimSpace(b)
		if b == "" || strings.HasPrefix(b, "entire/checkpoints") {
			continue
		}
		shadow = append(shadow, b)
	}
	return shadow
}

